import {
  DataTypes,
  Model,
  type CreationOptional,
  type InferAttributes,
  type InferCreationAttributes,
  type Sequelize,
} from 'sequelize';
import { User } from '../users/user.model';

export class Device extends Model<InferAttributes<Device>, InferCreationAttributes<Device>> {
  declare id: CreationOptional<number>;
  declare userId: number;
  /** Stable id generated by the client (Capacitor Device.getId() or a random id stored on web). */
  declare deviceUid: string;
  declare name: string | null;
  declare platform: string | null;
  declare status: CreationOptional<'active' | 'revoked'>;
  declare lastSeenAt: Date | null;
  declare lastIp: string | null;
  declare revokedAt: Date | null;
  declare revokedBy: number | null;
  /** SHA-256 of the biometric unlock secret kept in the app's secure storage (null = not set up). */
  declare unlockKeyHash: CreationOptional<string | null>;
  declare unlockEnrolledAt: CreationOptional<Date | null>;
  declare createdAt: CreationOptional<Date>;
  declare updatedAt: CreationOptional<Date>;
}

export class OtpChallenge extends Model<
  InferAttributes<OtpChallenge>,
  InferCreationAttributes<OtpChallenge>
> {
  declare id: string;
  declare userId: number | null;
  declare mobile: string;
  declare purpose: 'login' | 'new_device';
  declare codeHash: string;
  declare deviceUid: string | null;
  declare attempts: CreationOptional<number>;
  declare expiresAt: Date;
  declare consumedAt: Date | null;
  declare createdAt: CreationOptional<Date>;
  declare updatedAt: CreationOptional<Date>;
}

/** Failed sign-in attempts of a user; `deviceId` 0 = devices the user has not signed in on. */
export class SignInThrottle extends Model<
  InferAttributes<SignInThrottle>,
  InferCreationAttributes<SignInThrottle>
> {
  declare id: CreationOptional<number>;
  declare userId: number;
  declare deviceId: number;
  declare failures: CreationOptional<number>;
  declare lockedUntil: Date | null;
  declare lastFailureAt: Date | null;
  declare createdAt: CreationOptional<Date>;
  declare updatedAt: CreationOptional<Date>;
}

export class RefreshToken extends Model<
  InferAttributes<RefreshToken>,
  InferCreationAttributes<RefreshToken>
> {
  declare id: CreationOptional<number>;
  declare userId: number;
  declare deviceId: number;
  declare instituteId: number | null;
  declare tokenHash: string;
  declare expiresAt: Date;
  declare revokedAt: Date | null;
  declare createdAt: CreationOptional<Date>;
  declare updatedAt: CreationOptional<Date>;
}

export class ImpersonationSession extends Model<
  InferAttributes<ImpersonationSession>,
  InferCreationAttributes<ImpersonationSession>
> {
  declare id: CreationOptional<number>;
  declare superAdminId: number;
  declare targetUserId: number;
  declare instituteId: number;
  declare reason: string | null;
  declare ip: string | null;
  declare expiresAt: Date;
  declare endedAt: Date | null;
  declare createdAt: CreationOptional<Date>;
  declare updatedAt: CreationOptional<Date>;
}

const pk = { type: DataTypes.INTEGER.UNSIGNED, autoIncrement: true, primaryKey: true };
const uint = (allowNull = false) => ({ type: DataTypes.INTEGER.UNSIGNED, allowNull });
const ts = { createdAt: DataTypes.DATE, updatedAt: DataTypes.DATE };

export function initAuthModels(sequelize: Sequelize) {
  Device.init(
    {
      id: pk,
      userId: uint(),
      deviceUid: { type: DataTypes.STRING(128), allowNull: false },
      name: DataTypes.STRING(120),
      platform: DataTypes.STRING(20),
      status: { type: DataTypes.STRING(20), allowNull: false, defaultValue: 'active' },
      lastSeenAt: DataTypes.DATE,
      lastIp: DataTypes.STRING(64),
      revokedAt: DataTypes.DATE,
      revokedBy: uint(true),
      unlockKeyHash: DataTypes.STRING(64),
      unlockEnrolledAt: DataTypes.DATE,
      ...ts,
    },
    { sequelize, tableName: 'devices' },
  );
  OtpChallenge.init(
    {
      id: { type: DataTypes.STRING(36), primaryKey: true },
      userId: uint(true),
      mobile: { type: DataTypes.STRING(20), allowNull: false },
      purpose: { type: DataTypes.STRING(20), allowNull: false },
      codeHash: { type: DataTypes.STRING(64), allowNull: false },
      deviceUid: DataTypes.STRING(128),
      attempts: { type: DataTypes.INTEGER, allowNull: false, defaultValue: 0 },
      expiresAt: { type: DataTypes.DATE, allowNull: false },
      consumedAt: DataTypes.DATE,
      ...ts,
    },
    { sequelize, tableName: 'otp_challenges' },
  );
  SignInThrottle.init(
    {
      id: pk,
      userId: uint(),
      deviceId: { type: DataTypes.INTEGER.UNSIGNED, allowNull: false, defaultValue: 0 },
      failures: { type: DataTypes.INTEGER.UNSIGNED, allowNull: false, defaultValue: 0 },
      lockedUntil: DataTypes.DATE,
      lastFailureAt: DataTypes.DATE,
      ...ts,
    },
    { sequelize, tableName: 'sign_in_throttles' },
  );
  RefreshToken.init(
    {
      id: pk,
      userId: uint(),
      deviceId: uint(),
      instituteId: uint(true),
      tokenHash: { type: DataTypes.STRING(64), allowNull: false, unique: true },
      expiresAt: { type: DataTypes.DATE, allowNull: false },
      revokedAt: DataTypes.DATE,
      ...ts,
    },
    { sequelize, tableName: 'refresh_tokens' },
  );
  ImpersonationSession.init(
    {
      id: pk,
      superAdminId: uint(),
      targetUserId: uint(),
      instituteId: uint(),
      reason: DataTypes.STRING(255),
      ip: DataTypes.STRING(64),
      expiresAt: { type: DataTypes.DATE, allowNull: false },
      endedAt: DataTypes.DATE,
      ...ts,
    },
    { sequelize, tableName: 'impersonation_sessions' },
  );
}

export function associateAuthModels() {
  Device.belongsTo(User, { foreignKey: 'userId', as: 'user' });
  ImpersonationSession.belongsTo(User, { foreignKey: 'superAdminId', as: 'superAdmin' });
  ImpersonationSession.belongsTo(User, { foreignKey: 'targetUserId', as: 'targetUser' });
}
